<style>
.q-wrap{max-width:1450px;margin:auto;padding:26px 18px 48px;color:#24364b}.q-head{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-bottom:22px}.q-head h2{font-size:26px;font-weight:800;margin:0;color:#172d47}.q-muted{color:#8090a4;font-size:13px;margin:5px 0 0}.q-card{background:white;border:1px solid #e3eaf3;border-radius:17px;box-shadow:0 5px 22px rgba(25,50,85,.045);padding:22px;margin-bottom:20px}.q-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-bottom:20px}.q-stat{padding:19px 20px;background:#fff;border:1px solid #e5ecf5;border-radius:15px;position:relative;overflow:hidden}.q-stat:before{content:'';position:absolute;top:0;left:0;width:4px;height:100%;background:var(--accent,#2563eb)}.q-stat small{display:block;color:#77889d;font-weight:600}.q-stat strong{display:block;font-size:26px;margin-top:9px;color:#19314d}.q-btn{border:0;background:#2563eb;color:#fff!important;border-radius:10px;padding:11px 17px;display:inline-flex;align-items:center;justify-content:center;gap:7px;text-decoration:none!important;font-weight:650;font-size:13px;cursor:pointer}.q-btn:hover{background:#1d4ed8;color:#fff!important}.q-btn.soft{background:#eff5ff;color:#2355b6!important}.q-btn.red{background:#fff0f0;color:#bb253b!important}.q-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:20px}.q-search{display:flex;gap:8px;flex-wrap:wrap}.q-input,.q-select,.q-textarea{width:100%;min-height:46px;padding:10px 13px;border:1px solid #d8e2ee;border-radius:10px;background:#fff;color:#26394e;outline:none}.q-input:focus,.q-select:focus,.q-textarea:focus{border-color:#4484ee;box-shadow:0 0 0 3px rgba(37,99,235,.09)}.q-search .q-input{width:290px}.q-table-scroll{overflow-x:auto}.q-table{width:100%;border-collapse:separate;border-spacing:0;min-width:900px}.q-table th{background:#223b59;color:white;font-size:12px;font-weight:700;padding:15px 14px;text-align:left;white-space:nowrap}.q-table th:first-child{border-radius:9px 0 0 0}.q-table th:last-child{border-radius:0 9px 0 0}.q-table td{padding:15px 14px;border-bottom:1px solid #edf1f6;font-size:13px;vertical-align:middle}.q-table tbody tr:hover{background:#f8fbff}.q-badge{display:inline-block;padding:5px 10px;border-radius:50px;font-size:11px;font-weight:750;background:#eef2f7;color:#4d617a}.q-badge.passed{background:#e6f8ed;color:#16834d}.q-badge.failed{background:#ffebec;color:#b82739}.q-badge.pending{background:#fff5dd;color:#a66b09}.q-badge.partial{background:#e8f1ff;color:#265eb1}.q-actions{display:flex;gap:6px;align-items:center}.q-actions form{margin:0}.q-actions .q-btn{padding:7px 10px;font-size:12px}.q-progress{height:6px;background:#e8edf4;border-radius:6px;overflow:hidden;margin-top:7px;max-width:100px}.q-progress span{display:block;height:100%;background:#18a873;border-radius:6px}.q-section{border:1px solid #e3eaf3;border-radius:16px;background:#fff;overflow:hidden;margin-bottom:19px;box-shadow:0 4px 18px rgba(25,50,85,.035)}.q-section-top{padding:18px 22px;background:#f7faff;border-bottom:1px solid #e3eaf3;display:flex;gap:12px;align-items:center}.q-section-top .q-number{width:35px;height:35px;border-radius:10px;background:#e4eeff;color:#245bba;display:flex;align-items:center;justify-content:center;font-weight:800}.q-section-top h3{margin:0;font-size:16px;color:#1c3450;font-weight:800}.q-section-top p{margin:3px 0 0;font-size:12px;color:#8796a8}.q-section-body{padding:24px}.q-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.q-field label{display:block;font-size:13px;font-weight:700;color:#34465d;margin-bottom:8px}.q-field .q-help{font-size:11px;color:#8b99aa;margin-top:6px}.q-required{color:#dc3545}.q-error{font-size:12px;color:#c42638;margin-top:5px}.q-full{grid-column:1/-1}.q-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:22px}.q-summary>div{padding:16px;background:#f5f8fc;border:1px solid #e7edf5;border-radius:12px}.q-summary small{display:block;color:#7c8ca0;font-weight:600}.q-summary strong{font-size:21px;color:#1d3552}.q-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding-top:8px}.q-alert{background:#eaf8ef;color:#177443;border-radius:10px;padding:12px 16px;margin-bottom:16px}.q-alert.error{background:#fff0f0;color:#b92736}@media(max-width:850px){.q-stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.q-wrap{padding:16px 10px}.q-stats,.q-grid,.q-summary{grid-template-columns:1fr}.q-search,.q-search .q-input{width:100%}.q-card,.q-section-body{padding:16px}}
</style>
<div class="q-section">
    <div class="q-section-top"><span class="q-number">01</span><div><h3>Inspection Information</h3><p>Define inspection stage and link it to production records</p></div></div>
    <div class="q-section-body"><div class="q-grid">
        <div class="q-field"><label for="inspection_type">Inspection Type <span class="q-required">*</span></label><select class="q-select" id="inspection_type" name="inspection_type" required><option value="">Select inspection type</option>@foreach(['incoming'=>'Incoming Material','in_process'=>'In Process','final'=>'Final Inspection','random'=>'Random Inspection'] as $value=>$label)<option value="{{ $value }}" @selected((string)old('inspection_type',$inspection->inspection_type ?? '') === $value)>{{ $label }}</option>@endforeach</select>@error('inspection_type')<div class="q-error">{{ $message }}</div>@enderror</div>
        <div class="q-field"><label for="inspection_date">Inspection Date</label><input class="q-input" type="date" id="inspection_date" name="inspection_date" value="{{ old('inspection_date', isset($inspection) && $inspection->inspection_date ? \Illuminate\Support\Carbon::parse($inspection->inspection_date)->format('Y-m-d') : '') }}">@error('inspection_date')<div class="q-error">{{ $message }}</div>@enderror</div>
        <div class="q-field"><label for="production_order_id">Production Order</label><select class="q-select" id="production_order_id" name="production_order_id"><option value="">Select production order</option>@foreach(($productionOrders ?? collect()) as $option)<option value="{{ $option->id }}" @selected((string)old('production_order_id',$inspection->production_order_id ?? '') === (string)$option->id)>{{ $option->order_number ?? $option->id }}</option>@endforeach</select>@error('production_order_id')<div class="q-error">{{ $message }}</div>@enderror</div>
        <div class="q-field"><label for="work_order_id">Work Order</label><select class="q-select" id="work_order_id" name="work_order_id"><option value="">Select work order</option>@foreach(($workOrders ?? collect()) as $option)<option value="{{ $option->id }}" @selected((string)old('work_order_id',$inspection->work_order_id ?? '') === (string)$option->id)>{{ $option->work_order_number ?? $option->id }}</option>@endforeach</select>@error('work_order_id')<div class="q-error">{{ $message }}</div>@enderror</div>
    </div></div>
</div>
<div class="q-section">
    <div class="q-section-top"><span class="q-number">02</span><div><h3>Quantity & Quality Results</h3><p>Record tested, accepted and rejected quantities</p></div></div>
    <div class="q-section-body"><div class="q-grid">
        <div class="q-field"><label for="inspected_quantity">Inspected Quantity <span class="q-required">*</span></label><input class="q-input" type="number" min="0" step="any" id="inspected_quantity" name="inspected_quantity" required value="{{ old('inspected_quantity',$inspection->inspected_quantity ?? '') }}" placeholder="0.00">@error('inspected_quantity')<div class="q-error">{{ $message }}</div>@enderror</div>
        <div class="q-field"><label for="passed_quantity">Passed Quantity</label><input class="q-input" type="number" min="0" step="any" id="passed_quantity" name="passed_quantity" value="{{ old('passed_quantity',$inspection->passed_quantity ?? '') }}" placeholder="0.00">@error('passed_quantity')<div class="q-error">{{ $message }}</div>@enderror</div>
        <div class="q-field"><label for="failed_quantity">Failed Quantity</label><input class="q-input" type="number" min="0" step="any" id="failed_quantity" name="failed_quantity" value="{{ old('failed_quantity',$inspection->failed_quantity ?? '') }}" placeholder="0.00">@error('failed_quantity')<div class="q-error">{{ $message }}</div>@enderror</div>
        <div class="q-field"><label for="status">Inspection Status</label><select class="q-select" id="status" name="status"><option value="">Select status</option>@foreach(['pending'=>'Pending','passed'=>'Passed','failed'=>'Failed','partial'=>'Partial'] as $value=>$label)<option value="{{ $value }}" @selected((string)old('status',$inspection->status ?? '') === $value)>{{ $label }}</option>@endforeach</select>@error('status')<div class="q-error">{{ $message }}</div>@enderror</div>
    </div>
    <div class="q-summary"><div><small>Inspected Quantity</small><strong id="qTotalPreview">—</strong></div><div><small>Pass Rate</small><strong id="qRatePreview">—</strong></div><div><small>Quantity Balance</small><strong id="qBalancePreview">—</strong></div></div>
    <p class="q-muted" style="margin-top:13px">Quantity Balance = Inspected − Passed − Failed. A nonzero balance may represent unclassified or pending quantities. Ensure all quantities use the same unit.</p>
    </div>
</div>
<script>
(function(){function updateQualityPreview(){const get=id=>Math.max(0,parseFloat(document.getElementById(id)?.value)||0);const total=get('inspected_quantity'),passed=get('passed_quantity'),failed=get('failed_quantity');const fmt=n=>n.toLocaleString(undefined,{maximumFractionDigits:2});document.getElementById('qTotalPreview').textContent=fmt(total);document.getElementById('qRatePreview').textContent=total>0?fmt(passed/total*100)+'%':'—';const balance=total-passed-failed;const el=document.getElementById('qBalancePreview');el.textContent=fmt(balance);el.style.color=balance<0?'#b82739':'#1d3552';}['inspected_quantity','passed_quantity','failed_quantity'].forEach(id=>document.getElementById(id)?.addEventListener('input',updateQualityPreview));updateQualityPreview();})();
</script>
